147	static void insertEnum(IColumn & column, const DataTypePtr & column_type, const capnp::DynamicEnum & enum_value, FormatSettings::EnumComparingMode enum_comparing_mode)
148	{
149	    auto enumerant = *kj::_::readMaybe(enum_value.getEnumerant());
150	    auto enum_type = assert_cast<const DataTypeEnum<ValueType> *>(column_type.get());
151	    DataTypePtr nested_type = std::make_shared<DataTypeNumber<ValueType>>();
152	    switch (enum_comparing_mode)
153	    {
154	        case FormatSettings::EnumComparingMode::BY_VALUES:
155	            insertSignedInteger(column, nested_type, Int64(enumerant.getOrdinal()));
156	            return;
157	        case FormatSettings::EnumComparingMode::BY_NAMES:
158	            insertSignedInteger(column, nested_type, Int64(enum_type->getValue(String(enumerant.getProto().getName()))));
159	            return;
160	        case FormatSettings::EnumComparingMode::BY_NAMES_CASE_INSENSITIVE:
161	        {
162	            /// Find the same enum name case insensitive.
163	            String enum_name = enumerant.getProto().getName();
164	            for (auto & name : enum_type->getAllRegisteredNames())
165	            {
166	                if (compareEnumNames(name, enum_name, enum_comparing_mode))
167	                {
168	                    insertSignedInteger(column, nested_type, Int64(enum_type->getValue(name)));
169	                    break;
170	                }
171	            }
172	        }
173	    }
174	}
