176	static void insertValue(IColumn & column, const DataTypePtr & column_type, const capnp::DynamicValue::Reader & value, FormatSettings::EnumComparingMode enum_comparing_mode)
177	{
178	    if (column_type->lowCardinality())
179	    {
180	        auto & lc_column = assert_cast<ColumnLowCardinality &>(column);
181	        auto tmp_column = lc_column.getDictionary().getNestedColumn()->cloneEmpty();
182	        auto dict_type = assert_cast<const DataTypeLowCardinality *>(column_type.get())->getDictionaryType();
183	        insertValue(*tmp_column, dict_type, value, enum_comparing_mode);
184	        lc_column.insertFromFullColumn(*tmp_column, 0);
185	        return;
186	    }
187	
188	    switch (value.getType())
189	    {
190	        case capnp::DynamicValue::Type::INT:
191	            insertSignedInteger(column, column_type, value.as<Int64>());
192	            break;
193	        case capnp::DynamicValue::Type::UINT:
194	            insertUnsignedInteger(column, column_type, value.as<UInt64>());
195	            break;
196	        case capnp::DynamicValue::Type::FLOAT:
197	            insertFloat(column, column_type, value.as<Float64>());
198	            break;
199	        case capnp::DynamicValue::Type::BOOL:
200	            insertUnsignedInteger(column, column_type, UInt64(value.as<bool>()));
201	            break;
202	        case capnp::DynamicValue::Type::DATA:
203	            insertString(column, value.as<capnp::Data>());
204	            break;
205	        case capnp::DynamicValue::Type::TEXT:
206	            insertString(column, value.as<capnp::Text>());
207	            break;
208	        case capnp::DynamicValue::Type::ENUM:
209	            if (column_type->getTypeId() == TypeIndex::Enum8)
210	                insertEnum<Int8>(column, column_type, value.as<capnp::DynamicEnum>(), enum_comparing_mode);
211	            else
212	                insertEnum<Int16>(column, column_type, value.as<capnp::DynamicEnum>(), enum_comparing_mode);
213	            break;
214	        case capnp::DynamicValue::LIST:
215	        {
216	            auto list_value = value.as<capnp::DynamicList>();
217	            auto & column_array = assert_cast<ColumnArray &>(column);
218	            auto & offsets = column_array.getOffsets();
219	            offsets.push_back(offsets.back() + list_value.size());
220	
221	            auto & nested_column = column_array.getData();
222	            auto nested_type = assert_cast<const DataTypeArray *>(column_type.get())->getNestedType();
223	            for (const auto & nested_value : list_value)
224	                insertValue(nested_column, nested_type, nested_value, enum_comparing_mode);
225	            break;
226	        }
227	        case capnp::DynamicValue::Type::STRUCT:
228	        {
229	            auto struct_value = value.as<capnp::DynamicStruct>();
230	            if (column_type->isNullable())
231	            {
232	                auto & nullable_column = assert_cast<ColumnNullable &>(column);
233	                auto field = *kj::_::readMaybe(struct_value.which());
234	                if (field.getType().isVoid())
235	                    nullable_column.insertDefault();
236	                else
237	                {
238	                    auto & nested_column = nullable_column.getNestedColumn();
239	                    auto nested_type = assert_cast<const DataTypeNullable *>(column_type.get())->getNestedType();
240	                    auto nested_value = struct_value.get(field);
241	                    insertValue(nested_column, nested_type, nested_value, enum_comparing_mode);
242	                    nullable_column.getNullMapData().push_back(0);
243	                }
244	            }
245	            else
246	            {
247	                auto & tuple_column = assert_cast<ColumnTuple &>(column);
248	                const auto * tuple_type = assert_cast<const DataTypeTuple *>(column_type.get());
249	                for (size_t i = 0; i != tuple_column.tupleSize(); ++i)
250	                    insertValue(
251	                        tuple_column.getColumn(i),
252	                        tuple_type->getElements()[i],
253	                        struct_value.get(tuple_type->getElementNames()[i]),
254	                        enum_comparing_mode);
255	            }
256	            break;
257	        }
258	        default:
259	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Unexpected CapnProto value type.");
260	    }
261	}
