263	bool CapnProtoRowInputFormat::readRow(MutableColumns & columns, RowReadExtension &)
264	{
265	    if (in->eof())
266	        return false;
267	
268	    try
269	    {
270	        auto array = readMessage();
271	        capnp::FlatArrayMessageReader msg(array);
272	        auto root_reader = msg.getRoot<capnp::DynamicStruct>(root);
273	        for (size_t i = 0; i != columns.size(); ++i)
274	        {
275	            auto value = getReaderByColumnName(root_reader, column_names[i]);
276	            insertValue(*columns[i], column_types[i], value, format_settings.capn_proto.enum_comparing_mode);
277	        }
278	    }
279	    catch (const kj::Exception & e)
280	    {
281	        throw Exception(ErrorCodes::INCORRECT_DATA, "Cannot read row: {}", e.getDescription().cStr());
282	    }
283	
284	    return true;
285	}
